const OPENAI_KEY = 'YOUR_OPENAI_API_KEY';
const item = $input.first().json;
const msg = item.message || {};
const chatId = msg.chat && msg.chat.id;
const text = String(msg.text || '').trim();
if (!chatId || !text || text.startsWith('/start')) {
  return [{ json: { chatId, reply: 'Пришлите заявку одним сообщением: имя, телефон и что нужно.', skip: true } }];
}

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/chat/completions',
  headers: {
    Authorization: 'Bearer ' + OPENAI_KEY,
    'Content-Type': 'application/json',
  },
  body: {
    model: 'gpt-4o-mini',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: 'Извлеки заявку. Верни только JSON {\"name\":\"\",\"phone\":\"\",\"request\":\"\"}. Пустые поля оставь пустыми строками.' },
      { role: 'user', content: text },
    ],
  },
  json: true,
});

let parsed = { name: '', phone: '', request: text };
try {
  parsed = JSON.parse(resp.choices[0].message.content);
} catch (e) {}

return [{
  json: {
    chatId,
    name: parsed.name || '',
    phone: parsed.phone || '',
    request: parsed.request || text,
    sourceText: text,
    reply: 'Заявка принята. Имя: ' + (parsed.name || '—') + ', телефон: ' + (parsed.phone || '—'),
    skip: false,
  },
}];
